export default function Section() {
  return (
    <section className="relative overflow-hidden bg-gradient-to-br from-primary-100 via-surface to-accent-100">
      <div aria-hidden="true" className="pointer-events-none absolute -left-24 -top-24 h-72 w-72 rounded-full bg-primary-300/40 blur-3xl md:h-[28rem] md:w-[28rem]" />
      <div aria-hidden="true" className="pointer-events-none absolute -right-20 top-1/3 h-64 w-64 rounded-full bg-accent-300/40 blur-3xl md:h-96 md:w-96" />
      <div aria-hidden="true" className="pointer-events-none absolute -bottom-32 left-1/3 h-72 w-72 rounded-full bg-primary-300/30 blur-3xl" />

      <Category>
        {c => (
          <div className="relative mx-auto max-w-7xl px-4 pb-12 pt-6 sm:px-6 md:pb-20 md:pt-8 lg:px-8">
            <nav aria-label="Breadcrumb" className="inline-flex max-w-full flex-wrap items-center gap-1 rounded-full border border-white/60 bg-white/50 px-4 py-2 text-sm text-foreground-secondary shadow-lg shadow-primary-900/5 backdrop-blur-xl">
              <Breadcrumbs>
                {b => (
                  <span className="inline-flex items-center gap-1">
                    {b.url && !b.current ? (
                      <Link href={b.url} className="inline-flex min-h-11 items-center rounded-full px-1 transition-colors hover:text-primary-700">
                        {b.name}
                      </Link>
                    ) : (
                      <span aria-current="page" className="inline-flex min-h-11 items-center px-1 font-semibold text-secondary-900">
                        {b.name}
                      </span>
                    )}
                    {!b.current && <Icon name="chevron-right" size="xs" className="text-foreground-muted" />}
                  </span>
                )}
              </Breadcrumbs>
            </nav>

            <div className="mt-5 grid grid-cols-1 md:mt-6">
              {c.image && (
                <div className="col-start-1 row-start-1 overflow-hidden rounded-3xl border border-white/60 shadow-lg shadow-primary-900/10">
                  <div className="md:hidden">
                    <Image src={c.mobileImage || c.image} alt={c.name} aspect="4:5" fit="cover" sizes="100vw" priority />
                  </div>
                  <div className="hidden md:block lg:hidden">
                    <Image src={c.image} alt={c.name} aspect="16:9" fit="cover" sizes="100vw" />
                  </div>
                  <div className="hidden lg:block">
                    <Image src={c.image} alt={c.name} aspect="21:9" fit="cover" sizes="100vw" />
                  </div>
                </div>
              )}

              <div
                className={`relative z-10 col-start-1 mx-3 rounded-3xl border border-white/60 bg-white/60 p-6 shadow-lg shadow-primary-900/10 backdrop-blur-xl sm:mx-6 sm:p-8 md:row-start-1 md:mx-8 md:my-8 md:max-w-xl md:self-center md:justify-self-start md:p-10 lg:mx-12 ${c.image ? "row-start-2 -mt-24 sm:-mt-28" : "row-start-1 mx-0 sm:mx-0 md:mx-0"}`}
              >
                <div className="flex flex-wrap items-center gap-2">
                  {c.parentName && c.parentUrl && (
                    <Link
                      href={c.parentUrl}
                      className="inline-flex min-h-11 items-center gap-1 rounded-full bg-primary-700/10 px-4 text-sm font-semibold text-primary-700 transition-colors hover:bg-primary-700 hover:text-white"
                    >
                      <Icon name="arrow-left" size="xs" />
                      {c.parentName}
                    </Link>
                  )}
                  {c.productCount > 0 && (
                    <span className="inline-flex min-h-11 items-center gap-2 rounded-full border border-white/60 bg-white/60 px-4 text-sm font-medium text-secondary-900">
                      <Icon name="layers" size="xs" className="text-accent-700" />
                      {c.productCount} products
                    </span>
                  )}
                </div>

                <h1 className="mt-4 font-display text-4xl font-bold tracking-tight text-secondary-900 sm:text-5xl lg:text-6xl">
                  {c.name}
                </h1>

                {c.tagline && (
                  <p className="mt-3 text-lg font-medium text-primary-700 md:text-xl">
                    {c.tagline}
                  </p>
                )}

                {c.description && (
                  <p className="mt-4 text-base leading-relaxed text-foreground-secondary md:line-clamp-5">
                    {c.description}
                  </p>
                )}

                <SubCategories className="mt-6 flex flex-wrap gap-2">
                  {s => (
                    <Link
                      href={s.url}
                      className="inline-flex min-h-11 items-center gap-2 rounded-full border border-white/60 bg-white/70 px-4 text-base font-medium text-secondary-900 shadow-sm shadow-primary-900/5 transition-colors hover:bg-primary-700 hover:text-white"
                    >
                      {s.name}
                      <Icon name="arrow-up-right" size="xs" className="opacity-60" />
                    </Link>
                  )}
                </SubCategories>
              </div>
            </div>
          </div>
        )}
      </Category>
    </section>
  )
}

export default function Section() {
  return (
    <section className="relative overflow-hidden bg-gradient-to-br from-primary-100 via-surface to-accent-100">
      <div aria-hidden="true" className="pointer-events-none absolute -left-24 -top-24 h-72 w-72 rounded-full bg-primary-300/40 blur-3xl md:h-96 md:w-96" />
      <div aria-hidden="true" className="pointer-events-none absolute -right-20 top-1/3 h-64 w-64 rounded-full bg-accent-300/40 blur-3xl md:h-[28rem] md:w-[28rem]" />
      <div aria-hidden="true" className="pointer-events-none absolute bottom-0 left-1/3 h-56 w-56 rounded-full bg-primary-300/30 blur-3xl" />

      <div className="relative mx-auto max-w-7xl px-4 py-10 sm:px-6 md:py-16 lg:px-8">
        <Brand>
          {b => (
            <div>
              <div className="flex flex-wrap items-center gap-1 text-sm text-foreground-secondary">
                <Breadcrumbs>
                  {c => (
                    <span className="inline-flex items-center gap-1">
                      {c.url && !c.current ? (
                        <Link href={c.url} className="inline-flex min-h-11 items-center rounded-full px-2 hover:text-primary-700">
                          {c.name}
                        </Link>
                      ) : (
                        <span aria-current="page" className="inline-flex min-h-11 items-center px-2 font-semibold text-foreground">
                          {c.name}
                        </span>
                      )}
                      {!c.current && <Icon name="chevron-right" size="xs" className="text-foreground-muted" />}
                    </span>
                  )}
                </Breadcrumbs>
              </div>

              <div
                className={`relative mt-4 overflow-hidden rounded-3xl md:mt-6 ${
                  b.image
                    ? 'shadow-lg shadow-primary-900/10'
                    : 'border border-white/60 bg-white/30 shadow-lg shadow-primary-900/10 backdrop-blur-xl'
                }`}
              >
                {b.image && (
                  <div className="absolute inset-0">
                    <div className={b.mobileImage ? 'hidden h-full md:block' : 'h-full'}>
                      <Image
                        src={b.image}
                        alt=""
                        aspect="auto"
                        fit="cover"
                        priority={true}
                        sizes="100vw"
                        className="h-full w-full"
                      />
                    </div>
                    {b.mobileImage && (
                      <div className="h-full md:hidden">
                        <Image
                          src={b.mobileImage}
                          alt=""
                          aspect="auto"
                          fit="cover"
                          priority={true}
                          sizes="100vw"
                          className="h-full w-full"
                        />
                      </div>
                    )}
                    <div className="absolute inset-0 bg-gradient-to-t from-secondary-900/60 via-secondary-900/15 to-transparent md:bg-gradient-to-r md:from-secondary-900/40 md:via-transparent md:to-secondary-900/30" />
                  </div>
                )}

                <div
                  className={`relative grid grid-cols-1 items-end gap-5 p-4 sm:p-8 md:grid-cols-12 md:gap-8 md:p-12 ${
                    b.image ? 'pt-44 sm:pt-60 md:min-h-[30rem] md:pt-12' : 'md:min-h-[22rem]'
                  }`}
                >
                  <div className="md:col-span-4 lg:col-span-3">
                    <div className="w-36 rounded-3xl border border-white/60 bg-white/60 p-4 shadow-lg shadow-primary-900/10 backdrop-blur-xl sm:w-44 md:w-full md:p-6">
                      {b.logo ? (
                        <div className="overflow-hidden rounded-2xl bg-white/70">
                          <Image src={b.logo} alt={b.name} aspect="1:1" fit="contain" sizes="(min-width: 768px) 25vw, 176px" />
                        </div>
                      ) : (
                        <div className="flex aspect-square items-center justify-center rounded-2xl bg-gradient-to-br from-primary-100 to-accent-100 p-3">
                          <span className="text-center font-display text-xl font-bold tracking-tight text-primary-700 md:text-2xl">
                            {b.name}
                          </span>
                        </div>
                      )}
                    </div>
                  </div>

                  <div className="md:col-span-8 lg:col-span-9 lg:pl-4">
                    <div className="rounded-3xl border border-white/60 bg-white/60 p-5 shadow-lg shadow-primary-900/10 backdrop-blur-xl sm:p-8 lg:max-w-3xl">
                      <p className="inline-flex items-center gap-2 rounded-full bg-primary-100/80 px-3 py-1 text-xs font-semibold uppercase tracking-widest text-primary-700">
                        <Icon name="sparkles" size="xs" className="text-primary-700" />
                        Meet the maker
                      </p>

                      <h1 className="mt-3 font-display text-3xl font-bold tracking-tight text-secondary-900 sm:text-4xl lg:text-5xl">
                        {b.name}
                      </h1>

                      {b.tagline && (
                        <p className="mt-2 font-display text-lg tracking-tight text-accent-700 sm:text-xl">
                          {b.tagline}
                        </p>
                      )}

                      {b.description && (
                        <p className="mt-4 line-clamp-4 text-base leading-relaxed text-foreground-secondary">
                          {b.description}
                        </p>
                      )}

                      <dl className="mt-5 flex flex-wrap gap-2">
                        {b.founded && (
                          <div className="inline-flex items-center gap-2 rounded-full border border-white/60 bg-white/70 px-3 py-1.5 text-sm">
                            <Icon name="calendar" size="xs" className="text-primary-700" />
                            <dt className="text-foreground-muted">Since</dt>
                            <dd className="font-semibold text-secondary-900">{b.founded}</dd>
                          </div>
                        )}
                        {b.origin && (
                          <div className="inline-flex items-center gap-2 rounded-full border border-white/60 bg-white/70 px-3 py-1.5 text-sm">
                            <Icon name="globe" size="xs" className="text-primary-700" />
                            <dt className="text-foreground-muted">From</dt>
                            <dd className="font-semibold text-secondary-900">{b.origin}</dd>
                          </div>
                        )}
                        {b.headquarters && (
                          <div className="inline-flex items-center gap-2 rounded-full border border-white/60 bg-white/70 px-3 py-1.5 text-sm">
                            <Icon name="map-pin" size="xs" className="text-primary-700" />
                            <dt className="sr-only">Based in</dt>
                            <dd className="font-semibold text-secondary-900">{b.headquarters}</dd>
                          </div>
                        )}
                        {b.productCount > 0 && (
                          <div className="inline-flex items-center gap-2 rounded-full border border-white/60 bg-white/70 px-3 py-1.5 text-sm">
                            <Icon name="shopping-bag" size="xs" className="text-primary-700" />
                            <dt className="sr-only">In store</dt>
                            <dd className="font-semibold text-secondary-900">
                              {b.productCount} <span className="font-normal text-foreground-muted">in store</span>
                            </dd>
                          </div>
                        )}
                      </dl>

                      <div className="mt-6 flex flex-wrap items-center gap-2 sm:gap-3">
                        {b.website && (
                          <Link
                            href={b.website}
                            target="_blank"
                            className="inline-flex min-h-11 items-center gap-2 rounded-full bg-primary-700 px-5 text-sm font-semibold text-white shadow-lg shadow-primary-900/20 transition hover:bg-primary-800"
                          >
                            Visit their website
                            <Icon name="arrow-up-right" size="sm" className="text-white" />
                          </Link>
                        )}
                        {b.socials.map(s => (
                          <Link
                            href={s.href}
                            target="_blank"
                            className="inline-flex min-h-11 items-center gap-1.5 rounded-full border border-white/60 bg-white/70 px-4 text-sm font-medium text-secondary-900 backdrop-blur-xl transition hover:bg-white"
                          >
                            {s.label}
                            <Icon name="arrow-up-right" size="xs" className="text-accent-700" />
                          </Link>
                        ))}
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          )}
        </Brand>
      </div>
    </section>
  )
}

export default function Section() {
  return (
    <section className="relative overflow-hidden bg-gradient-to-br from-primary-100 via-surface to-accent-100 pb-16 pt-6 md:pb-28 md:pt-10">
      {/* aurora mesh */}
      <div aria-hidden="true" className="pointer-events-none absolute -left-24 -top-24 h-72 w-72 rounded-full bg-primary-300/40 blur-3xl md:h-[28rem] md:w-[28rem]" />
      <div aria-hidden="true" className="pointer-events-none absolute -right-20 top-40 h-64 w-64 rounded-full bg-accent-300/40 blur-3xl md:h-[26rem] md:w-[26rem]" />
      <div aria-hidden="true" className="pointer-events-none absolute bottom-0 left-1/3 h-56 w-56 rounded-full bg-primary-300/30 blur-3xl md:h-80 md:w-80" />

      <div className="relative mx-auto max-w-7xl px-4 sm:px-6 lg:px-8">
        {/* slim title band */}
        <header className="rounded-3xl border border-white/60 bg-white/60 px-5 py-5 shadow-lg shadow-primary-900/10 backdrop-blur-xl sm:px-8 md:py-6">
          <nav aria-label="Breadcrumb">
            <Breadcrumbs className="flex flex-wrap items-center gap-x-1 text-base text-foreground-secondary">
              {c => (
                <span className="inline-flex items-center gap-1">
                  {c.url ? (
                    <Link
                      href={c.url}
                      className="inline-flex min-h-11 items-center rounded-full px-2 text-foreground-secondary transition-colors hover:bg-white/70 hover:text-primary-700"
                    >
                      {c.name}
                    </Link>
                  ) : (
                    <span aria-current="page" className="inline-flex min-h-11 items-center px-2 font-medium text-foreground">
                      {c.name}
                    </span>
                  )}
                  {!c.current && <Icon name="chevron-right" size="xs" className="text-foreground-muted" />}
                </span>
              )}
            </Breadcrumbs>
          </nav>

          <div className="mt-3 flex flex-col gap-3 md:mt-2 md:flex-row md:items-end md:justify-between md:gap-8">
            <div className="flex items-center gap-3">
              <span className="flex h-11 w-11 shrink-0 items-center justify-center rounded-2xl bg-gradient-to-br from-primary-200 to-accent-200 text-primary-700">
                <Icon name="layers" size="md" />
              </span>
              <h1 className="font-display text-3xl font-bold tracking-tight text-foreground sm:text-4xl md:text-5xl">
                Brands we carry
              </h1>
            </div>
            <p className="max-w-md text-base text-foreground-secondary md:text-right">
              Every name on our shelves, in one place. Pick one to see all it makes.
            </p>
          </div>
        </header>

        {/* wide grid */}
        <AllBrands className="mt-8 grid grid-cols-1 gap-4 sm:grid-cols-2 sm:gap-5 md:mt-12 lg:grid-cols-3 xl:grid-cols-4">
          {b => (
            <Link
              href={b.url}
              className={`group relative flex h-full flex-col rounded-3xl border border-white/60 p-3 shadow-lg shadow-primary-900/10 backdrop-blur-xl transition duration-300 hover:-translate-y-1 hover:shadow-xl hover:shadow-primary-900/20 ${
                b.featured ? 'bg-white/70 ring-2 ring-primary-300/60' : 'bg-white/50'
              }`}
            >
              <div className="relative overflow-hidden rounded-2xl bg-gradient-to-br from-primary-50 via-white to-accent-50">
                {b.logo ? (
                  <div className="p-6 sm:p-8">
                    <Image
                      src={b.logo}
                      alt={b.name}
                      aspect="3:2"
                      fit="contain"
                      sizes="(min-width: 1280px) 25vw, (min-width: 1024px) 33vw, (min-width: 640px) 50vw, 100vw"
                    />
                  </div>
                ) : (
                  <div className="flex aspect-[3/2] items-center justify-center px-6">
                    <span className="text-center font-display text-2xl font-bold tracking-tight text-primary-700 sm:text-3xl">
                      {b.name}
                    </span>
                  </div>
                )}
                {b.featured && (
                  <span className="absolute left-3 top-3 inline-flex items-center gap-1 rounded-full border border-white/60 bg-white/80 px-3 py-1 text-sm font-medium text-primary-700 backdrop-blur-xl">
                    <Icon name="sparkles" size="xs" />
                    Featured
                  </span>
                )}
              </div>

              <div className="flex flex-1 flex-col px-2 pb-2 pt-4">
                <h2 className="font-display text-xl font-semibold tracking-tight text-foreground">
                  {b.name}
                </h2>
                {b.tagline && (
                  <p className="mt-1 text-base text-foreground-secondary">{b.tagline}</p>
                )}
                <div className="mt-auto flex items-center justify-between gap-3 pt-4">
                  <span className="inline-flex items-center gap-1.5 rounded-full bg-accent-100/80 px-3 py-1 text-sm font-medium text-accent-700">
                    <Icon name="shopping-bag" size="xs" />
                    {b.productCount} products
                  </span>
                  <span className="flex h-11 w-11 shrink-0 items-center justify-center rounded-full bg-primary-700 text-white transition-colors group-hover:bg-primary-800">
                    <Icon name="arrow-up-right" size="sm" />
                  </span>
                </div>
              </div>
            </Link>
          )}
        </AllBrands>
      </div>
    </section>
  )
}

export default function Section() {
  return (
    <section className="mx-auto w-full max-w-6xl px-4 py-8 md:py-12">
      <div className="flex flex-col gap-6">
        <WishlistGrid />
      </div>
    </section>
  )
}
